<?php

namespace HoseinMomeni\MahexWoo\V1;

use HoseinMomeni\MahexWoo\Admin\PackagingProfiles;
use HoseinMomeni\MahexWoo\Enterprise\Roles;
use HoseinMomeni\MahexWoo\Shipping\PricingSettings;

final class Admin {
	private const PAGE = 'hm-mahex-v1';

	public static function register(): void {
		add_action( 'admin_menu', array( self::class, 'menu' ), 20 );
		add_action( 'admin_enqueue_scripts', array( self::class, 'assets' ) );
		foreach ( array(
			'hm_mahex_v1_save_settings'=>'saveSettings','hm_mahex_v1_save_rules'=>'saveRules','hm_mahex_v1_repair'=>'repair','hm_mahex_v1_backup'=>'backup',
			'hm_mahex_v1_restore'=>'restore','hm_mahex_v1_export'=>'export','hm_mahex_v1_import'=>'import','hm_mahex_v1_partial_reset'=>'partialReset',
			'hm_mahex_v1_factory_reset'=>'factoryReset','hm_mahex_v1_inventory_adjust'=>'inventoryAdjust','hm_mahex_v1_qualification'=>'qualification',
			'hm_mahex_v1_save_dashboard'=>'saveDashboard','hm_mahex_v1_save_filter'=>'saveFilter','hm_mahex_v1_bulk_edit'=>'bulkEdit','hm_mahex_v1_reindex'=>'reindex',
			'hm_mahex_v1_print_enqueue'=>'printEnqueue','hm_mahex_v1_print_mark'=>'printMark',
		) as $hook => $method ) add_action( 'admin_post_' . $hook, array( self::class, $method ) );
	}

	public static function menu(): void {
		add_submenu_page( 'hm-mahex', 'Mahex Shipping Core', 'مرکز اصلی', 'read', self::PAGE, array( self::class, 'render' ) );
	}

	public static function assets( string $hook ): void {
		if ( false === strpos( $hook, self::PAGE ) ) return;
		wp_enqueue_style( 'hm-mahex-admin', plugins_url( 'assets/admin/dashboard.css', HM_MAHEX_FILE ), array(), HM_MAHEX_VERSION );
		wp_add_inline_style( 'hm-mahex-admin', '.hmv1-tabs{display:flex;gap:6px;flex-wrap:wrap;margin:14px 0}.hmv1-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.hmv1-card{background:#fff;border:1px solid #dbe3ec;border-radius:14px;padding:16px}.hmv1-card h2,.hmv1-card h3{margin-top:0}.hmv1-kpi b{display:block;font-size:25px;color:#082e63}.hmv1-two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.hmv1-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.hmv1-form label{display:flex;flex-direction:column;gap:5px}.hmv1-form input,.hmv1-form select,.hmv1-form textarea{width:100%;max-width:none}.hmv1-section{margin:14px 0}.hmv1-rule{background:#fff;border:1px solid #dbe3ec;border-radius:12px;padding:12px;margin:10px 0}.hmv1-code{direction:ltr;text-align:left;background:#f8fafc;padding:8px;border-radius:8px}.hmv1-ok{color:#067647}.hmv1-bad{color:#b42318}.hmv1-warn{color:#b54708}.hmv1-command{position:sticky;top:32px;z-index:10;background:#fff;border:1px solid #dbe3ec;padding:8px;border-radius:10px;margin:10px 0}.hmv1-command input{width:100%}@media(max-width:1000px){.hmv1-grid,.hmv1-form,.hmv1-two{grid-template-columns:1fr 1fr}}@media(max-width:700px){.hmv1-grid,.hmv1-form,.hmv1-two{grid-template-columns:1fr}}' );
		wp_add_inline_script( 'jquery-core', 'document.addEventListener("DOMContentLoaded",()=>{const q=document.querySelector("#hmv1-command");if(!q)return;q.addEventListener("keydown",e=>{if(e.key!=="Enter")return;const v=q.value.trim().toLowerCase();const map={"نرخ":"pricing","قیمت":"pricing","بسته":"packing","انبار":"inventory","چاپ":"labels","عملیات":"operations","گزارش":"reports","سلامت":"diagnostics","ابزار":"tools","rule":"rules"};for(const k in map){if(v.includes(k)){location.href="'.esc_js(admin_url('admin.php?page='.self::PAGE.'&tab=')).'"+map[k];break;}}});});' );
	}

	public static function render(): void {
		self::access(); $tab=sanitize_key((string)($_GET['tab']??'overview'));
		$tabs=array('overview'=>'داشبورد');
		if(Roles::canSettings()||Roles::canManage()){$tabs['pricing']='قیمت و سود';$tabs['rules']='Rule Builder';}
		if(Roles::canPack()||Roles::canManage())$tabs['packing']='بسته‌بندی';
		if(Roles::canInventory()||Roles::canManage())$tabs['inventory']='موجودی';
		if(Roles::canPack()||Roles::canManage())$tabs['operations']='عملیات';
		if(Roles::canPrint()||Roles::canManage())$tabs['labels']='چاپ';
		if(Roles::canReport()||Roles::canManage())$tabs['reports']='گزارش';
		if(Roles::canSettings()||Roles::canManage()){$tabs['diagnostics']='عیب‌یابی';$tabs['tools']='ابزارها';}
		if(!isset($tabs[$tab]))$tab='overview';
		echo '<div class="wrap hm-mahex" dir="rtl"><h1>Mahex Shipping for WooCommerce <small style="font-size:14px">2.x Core</small></h1><p>مرکز محلی مدیریت ارسال، نرخ، بسته‌بندی، انبار و عملیات؛ بدون اتصال API خارجی.</p>';self::notice();
		echo '<div class="hmv1-command"><input id="hmv1-command" placeholder="فرمان سریع: نرخ، بسته‌بندی، چاپ، گزارش، سلامت… (Enter)"></div><nav class="nav-tab-wrapper hmv1-tabs">';foreach($tabs as $k=>$label)echo '<a class="nav-tab '.($tab===$k?'nav-tab-active':'').'" href="'.esc_url(admin_url('admin.php?page='.self::PAGE.'&tab='.$k)).'">'.esc_html($label).'</a>';echo '</nav>';
		match($tab){'pricing'=>self::pricing(),'rules'=>self::rules(),'packing'=>self::packing(),'inventory'=>self::inventory(),'operations'=>self::operations(),'labels'=>self::labels(),'reports'=>self::reports(),'diagnostics'=>self::diagnostics(),'tools'=>self::tools(),default=>self::overview()};echo '</div>';
	}

	private static function overview(): void {
		$days=max(1,min(3650,absint($_GET['days']??30)));$summary=Reports::summary($days);$activity=ActivityLog::recent(15);$q=isset($_GET['s'])?sanitize_text_field(wp_unslash($_GET['s'])):'';$found=$q!==''?OrderIndex::search($q,50):array();$widgets=get_option(Config::DASHBOARD_WIDGETS,array('orders','profit','inventory','activity'));$widgets=is_array($widgets)?$widgets:array();
		echo '<form method="get" style="margin:10px 0"><input type="hidden" name="page" value="'.self::PAGE.'"><input type="hidden" name="tab" value="overview"><select name="days"><option value="1" '.selected($days,1,false).'>امروز</option><option value="7" '.selected($days,7,false).'>۷ روز</option><option value="30" '.selected($days,30,false).'>۳۰ روز</option><option value="90" '.selected($days,90,false).'>۹۰ روز</option><option value="365" '.selected($days,365,false).'>یک سال</option></select> <button class="button">اعمال بازه</button></form>';
		echo '<div class="hmv1-grid">';
		if(in_array('orders',$widgets,true))self::kpi('سفارش در بازه',$summary['orders']);
		if(in_array('profit',$widgets,true)){self::money('درآمد ارسال',$summary['shipping']);self::money('سود خالص',$summary['profit']);}
		if(in_array('packing',$widgets,true))self::money('درآمد بسته‌بندی',$summary['packaging']);
		if(in_array('returns',$widgets,true))self::money('هزینه برگشتی',$summary['return_cost']);
		if(in_array('inventory',$widgets,true)){ $stock=InventoryLedger::lowAndCritical(); self::kpi('هشدار موجودی بسته',count($stock['low'])+count($stock['critical'])); }
		echo '</div>';
		echo '<div class="hmv1-two hmv1-section"><section class="hmv1-card"><h2>جست‌وجوی سراسری</h2><form method="get"><input type="hidden" name="page" value="'.self::PAGE.'"><input type="hidden" name="tab" value="overview"><input type="hidden" name="days" value="'.$days.'"><input class="regular-text" name="s" value="'.esc_attr($q).'" placeholder="سفارش، مشتری، موبایل، رهگیری، شهر، کدپستی"> <button class="button">جست‌وجو</button></form>';
		if($found){echo '<table class="widefat striped"><thead><tr><th>سفارش</th><th>مشتری</th><th>شهر</th><th>رهگیری</th><th>سود</th></tr></thead><tbody>';foreach($found as $r)echo '<tr><td>#'.esc_html($r['order_number']).'</td><td>'.esc_html($r['customer_name']).'</td><td>'.esc_html($r['city']).'</td><td dir="ltr">'.esc_html($r['tracking']).'</td><td>'.wp_kses_post(wc_price((float)$r['profit'])).'</td></tr>';echo '</tbody></table>';}echo '</section>';
		echo '<section class="hmv1-card"><h2>ویجت‌های داشبورد</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_save_dashboard">';wp_nonce_field('hm_mahex_v1_save_dashboard');foreach(array('orders'=>'سفارش‌ها','profit'=>'سود','inventory'=>'موجودی بسته','activity'=>'فعالیت‌ها','returns'=>'برگشتی‌ها','packing'=>'بسته‌بندی') as $k=>$label)echo '<label style="display:block;margin:7px"><input type="checkbox" name="widgets[]" value="'.esc_attr($k).'" '.checked(in_array($k,$widgets,true),true,false).'> '.esc_html($label).'</label>';submit_button('ذخیره چینش','secondary','',false);echo '</form><hr><h3>ذخیره فیلتر</h3><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_save_filter">';wp_nonce_field('hm_mahex_v1_save_filter');echo '<input name="name" placeholder="نام فیلتر"><input name="query" value="'.esc_attr($q).'" placeholder="عبارت جست‌وجو"> <button class="button">ذخیره</button></form>';self::savedFilters();echo '</section></div>';
		if(in_array('activity',$widgets,true)){echo '<section class="hmv1-card hmv1-section"><h2>آخرین فعالیت‌ها</h2><table class="widefat striped"><thead><tr><th>زمان</th><th>رویداد</th><th>سفارش</th><th>توضیح</th></tr></thead><tbody>';foreach($activity as $r)echo '<tr><td>'.esc_html((string)$r['created_at']).'</td><td>'.esc_html((string)$r['event_type']).'</td><td>'.((int)$r['order_id']?'#'.(int)$r['order_id']:'—').'</td><td>'.esc_html((string)$r['message']).'</td></tr>';echo '</tbody></table></section>';}
	}

	private static function pricing(): void { $s=Config::all();echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_save_settings">';wp_nonce_field('hm_mahex_v1_save_settings');echo '<section class="hmv1-card"><h2>کنترل سود و قیمت‌گذاری</h2><div class="hmv1-form">';self::num('min_shipping_margin_irr','حداقل سود ارسال (ریال)',$s);self::num('margin_percent','سود درصدی',$s,'0.01');self::num('margin_fixed_irr','سود ثابت (ریال)',$s);self::num('max_customer_shipping_irr','سقف کرایه مشتری (ریال)',$s);self::num('subsidy_percent','یارانه فروشگاه (%)',$s,'0.01');self::num('customer_share_percent','سهم مشتری از کرایه (%)',$s,'0.01');self::num('rounding_step_irr','پله گردکردن (ریال)',$s);self::num('psychological_ending_irr','پایان قیمت روانی (ریال)',$s);echo '</div>';self::area('margin_tiers','سود پلکانی: حداقل|حداکثر|درصد|مبلغ ثابت',$s,'0|1000000|5|0');echo '<p>محاسبه با اعداد صحیح انجام می‌شود تا خطای اعشاری باعث یک پله اضافه نشود.</p></section><section class="hmv1-card hmv1-section"><h2>Feature Flags و پایداری</h2>';foreach(array('safe_mode'=>'Safe Mode','large_store_mode'=>'Large Store Mode','profiler_enabled'=>'Performance Profiler','sensitive_lock'=>'قفل تنظیمات حساس','feature_pricing'=>'موتور قیمت','feature_packing'=>'موتور بسته‌بندی','feature_inventory'=>'موجودی','feature_operations'=>'عملیات انبار','feature_customer'=>'تجربه مشتری','feature_reporting'=>'گزارش‌ها') as $k=>$l)self::check($k,$l,$s);echo '</section>';submit_button('ذخیره تنظیمات نسخه 1');echo '</form>'; $sim=isset($_GET['sim_base'])?max(0,(float)$_GET['sim_base']):null;echo '<section class="hmv1-card hmv1-section"><h2>Margin Simulator</h2><form method="get"><input type="hidden" name="page" value="'.self::PAGE.'"><input type="hidden" name="tab" value="pricing"><input type="number" min="0" name="sim_base" placeholder="کرایه پایه (ریال)" value="'.esc_attr(null===$sim?'':(string)$sim).'"> <button class="button">محاسبه</button></form>';if(null!==$sim){$r=MarginEngine::apply($sim);echo '<p>کرایه پایه: <b>'.number_format_i18n((int)$sim).'</b> ریال → مبلغ مشتری: <b>'.number_format_i18n((int)$r['freight']).'</b> ریال · یارانه/سهم فروشگاه: <b>'.number_format_i18n((int)$r['subsidy']).'</b> ریال</p><code class="hmv1-code">'.esc_html(implode(' | ',$r['breakdown'])).'</code>';}echo '</section>'; }

	private static function rules(): void { $rows=RuleEngine::rules();for($i=count($rows);$i<min(5,count($rows)+2);$i++)$rows[]=array('id'=>'','name'=>'','active'=>true,'priority'=>100+$i,'logic'=>'AND','stop'=>false,'mode'=>'surcharge','amount'=>0);echo '<p>شرط‌های خالی نادیده گرفته می‌شوند. در حالت AND همه شرط‌های تکمیل‌شده باید برقرار باشند؛ در OR یکی کافی است.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_save_rules">';wp_nonce_field('hm_mahex_v1_save_rules');foreach($rows as $i=>$r){echo '<article class="hmv1-rule"><input type="hidden" name="rules['.$i.'][id]" value="'.esc_attr((string)($r['id']??'')).'"><div class="hmv1-form">';self::rawText("rules[$i][name]",'نام قانون',(string)($r['name']??''));self::rawNum("rules[$i][priority]",'اولویت',(string)($r['priority']??100));self::rawSelect("rules[$i][logic]",'منطق',(string)($r['logic']??'AND'),array('AND'=>'AND','OR'=>'OR'));self::rawSelect("rules[$i][mode]",'عمل',(string)($r['mode']??'surcharge'),array('surcharge'=>'افزایش ثابت','fixed'=>'نرخ ثابت','percent'=>'افزایش درصدی','discount'=>'تخفیف درصدی','free'=>'رایگان'));self::rawNum("rules[$i][amount]",'مقدار',(string)($r['amount']??0),'0.01');self::rawText("rules[$i][province]",'استان',(string)($r['province']??''));self::rawText("rules[$i][city]",'شهر',(string)($r['city']??''));self::rawNum("rules[$i][min_weight_g]",'حداقل وزن g',(string)($r['min_weight_g']??0));self::rawNum("rules[$i][max_weight_g]",'حداکثر وزن g',(string)($r['max_weight_g']??0));self::rawNum("rules[$i][min_qty]",'حداقل تعداد',(string)($r['min_qty']??0));self::rawNum("rules[$i][max_qty]",'حداکثر تعداد',(string)($r['max_qty']??0));self::rawNum("rules[$i][min_cart_irr]",'حداقل سبد ریال',(string)($r['min_cart_irr']??0));self::rawNum("rules[$i][max_cart_irr]",'حداکثر سبد ریال',(string)($r['max_cart_irr']??0));self::rawText("rules[$i][categories]",'دسته‌ها (slug)',implode(',',(array)($r['categories']??array())));self::rawText("rules[$i][shipping_classes]",'Shipping Class',implode(',',(array)($r['shipping_classes']??array())));self::rawText("rules[$i][brands]",'برندها (slug)',implode(',',(array)($r['brands']??array())));echo '</div><label><input type="checkbox" name="rules['.$i.'][active]" value="1" '.checked(!empty($r['active']),true,false).'> فعال</label> &nbsp; <label><input type="checkbox" name="rules['.$i.'][stop]" value="1" '.checked(!empty($r['stop']),true,false).'> پس از اجرا ادامه Ruleها متوقف شود</label></article>';}submit_button('ذخیره Ruleها');echo '</form>'; }

	private static function packing(): void { $s=Config::all();$orderId=absint($_GET['order_id']??0);$plan=null;if($orderId){$o=wc_get_order($orderId);if($o)$plan=PackingEngine::plan(self::packageFromOrder($o));}echo '<div class="hmv1-two"><section class="hmv1-card"><h2>تنظیمات موتور بسته‌بندی</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_save_settings">';wp_nonce_field('hm_mahex_v1_save_settings');echo '<div class="hmv1-form">';self::num('packing_waste_percent','فضای خالی/ضایعات (%)',$s,'0.1');self::num('packing_max_units','حداکثر واحد در یک محاسبه',$s);self::num('critical_stock_threshold','آستانه موجودی بحرانی',$s);echo '</div>';self::check('packing_verification','الزام تأیید بسته‌بندی',$s);self::check('barcode_verification','تأیید با بارکد/SKU',$s);self::check('auto_ready_to_ship','آماده‌ارسال خودکار در صورت عدم الزام تأیید',$s);self::area('order_columns','ستون‌های عملیات (order,customer,status,city,total,quick)',$s,'order,customer,status,city,total,quick');submit_button('ذخیره','secondary','',false);echo '</form><p><a class="button" href="'.esc_url(admin_url('admin.php?page=hm-mahex-packaging-profiles')).'">مدیریت پروفایل‌های بسته‌بندی</a></p></section><section class="hmv1-card"><h2>پیش‌نمایش بسته‌بندی سفارش</h2><form method="get"><input type="hidden" name="page" value="'.self::PAGE.'"><input type="hidden" name="tab" value="packing"><input type="number" name="order_id" min="1" placeholder="Order ID" value="'.($orderId?:'').'"> <button class="button">محاسبه</button></form>';if(is_array($plan)){echo '<p><strong>'.(int)$plan['package_count'].'</strong> بسته · هزینه '.number_format_i18n((int)$plan['cost_irr']).' ریال · وزن قابل محاسبه '.number_format_i18n((int)$plan['chargeable_weight_g']).' گرم</p><table class="widefat striped"><thead><tr><th>بسته</th><th>پروفایل</th><th>اقلام</th><th>وزن</th><th>حجمی</th></tr></thead><tbody>';foreach($plan['packages'] as $i=>$b)echo '<tr><td>'.($i+1).'</td><td>'.esc_html((string)$b['profile_name']).'</td><td>'.count((array)$b['items']).'</td><td>'.number_format_i18n((int)$b['actual_weight_g']).'g</td><td>'.number_format_i18n((int)$b['volumetric_weight_g']).'g</td></tr>';echo '</tbody></table>';if($plan['warnings'])echo '<p class="hmv1-warn">'.esc_html(implode(' | ',$plan['warnings'])).'</p>';}echo '</section></div>'; }

	private static function inventory(): void { $profiles=PackagingProfiles::all();$status=InventoryLedger::lowAndCritical();echo '<div class="hmv1-grid">';self::kpi('نوع بسته',count($profiles));self::kpi('هشدار کمبود',count($status['low']));self::kpi('بحرانی',count($status['critical']));echo '<div class="hmv1-card hmv1-kpi"><b>'.number_format_i18n(InventoryLedger::valuation()).'</b><span>ارزش موجودی (ریال)</span></div></div><section class="hmv1-card hmv1-section"><h2>شمارش/اصلاح موجودی</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_inventory_adjust">';wp_nonce_field('hm_mahex_v1_inventory_adjust');echo '<select name="profile_id">';foreach($profiles as $id=>$p)echo '<option value="'.esc_attr($id).'">'.esc_html((string)($p['name']??$id)).' — '.(int)($p['stock']??0).'</option>';echo '</select> <input type="number" min="0" name="new_stock" required placeholder="موجودی واقعی"> <input name="reason" required placeholder="دلیل اصلاح"> <button class="button button-primary">ثبت Adjustment</button></form></section><section class="hmv1-card hmv1-section"><h2>دفتر موجودی</h2><table class="widefat striped"><thead><tr><th>زمان</th><th>بسته</th><th>جهت</th><th>تعداد</th><th>مانده</th><th>سفارش</th><th>دلیل</th></tr></thead><tbody>';foreach(InventoryLedger::recent(100) as $r)echo '<tr><td>'.esc_html($r['created_at']).'</td><td>'.esc_html((string)($profiles[$r['profile_id']]['name']??$r['profile_id'])).'</td><td>'.esc_html($r['direction']).'</td><td>'.(int)$r['quantity'].'</td><td>'.(int)$r['balance_after'].'</td><td>'.((int)$r['order_id']?'#'.(int)$r['order_id']:'—').'</td><td>'.esc_html($r['reason']).'</td></tr>';echo '</tbody></table></section>'; }

	private static function operations(): void {
		$orders = wc_get_orders( array( 'limit'=>80, 'status'=>array('wc-processing','wc-on-hold'), 'orderby'=>'date', 'order'=>'DESC' ) );
		$result = get_transient( 'hm_mahex_pack_result_' . get_current_user_id() );
		if ( is_array( $result ) ) {
			delete_transient( 'hm_mahex_pack_result_' . get_current_user_id() );
			echo '<div class="notice '.(!empty($result['ok'])?'notice-success':'notice-error').' inline"><p>'.(!empty($result['ok'])?'بسته‌بندی تأیید شد.':'مغایرت: کمبود '.esc_html(wp_json_encode($result['missing'],JSON_UNESCAPED_UNICODE)).' | اضافه '.esc_html(wp_json_encode($result['wrong'],JSON_UNESCAPED_UNICODE))).'</p></div>';
		}
		$allowed = array('order','customer','status','city','total','quick');
		$columns = array_values( array_intersect( explode( ',', (string) Config::get( 'order_columns', 'order,customer,status,city,total,quick' ) ), $allowed ) );
		if ( ! $columns ) $columns = $allowed;
		echo '<section class="hmv1-card"><h2>Batch Picking / Packing</h2><p class="description">ستون‌های این جدول از تنظیمات موتور بسته‌بندی قابل انتخاب‌اند.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" target="_blank"><table class="widefat striped"><thead><tr><th></th>';
		$labels=array('order'=>'سفارش','customer'=>'مشتری','status'=>'وضعیت بسته','city'=>'شهر','total'=>'مبلغ','quick'=>'Quick View');foreach($columns as $c)echo '<th>'.esc_html($labels[$c]).'</th>';echo '</tr></thead><tbody>';
		foreach ( $orders as $o ) {
