		echo '<section class="hmv1-card hmv1-section"><h2>صف چاپ</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="display:flex;gap:8px;align-items:end;flex-wrap:wrap"><input type="hidden" name="action" value="hm_mahex_v1_print_enqueue">';wp_nonce_field('hm_mahex_v1_print_enqueue');echo '<label>شماره سفارش<br><input type="number" name="order_id" min="1" required></label><label>سند<br><select name="document_type"><option value="label">لیبل</option><option value="waybill">بارنامه</option><option value="combined">ترکیبی</option><option value="pick">Pick List</option><option value="packing">Packing List</option></select></label><label>کپی<br><input type="number" name="copies" min="1" max="100" value="1"></label><button class="button button-primary">افزودن به صف</button></form><table class="widefat striped" style="margin-top:12px"><thead><tr><th>ID</th><th>سفارش</th><th>نوع</th><th>کپی</th><th>زمان</th><th>عملیات</th></tr></thead><tbody>';foreach(PrintManager::pending(100) as $r){$print='';if(in_array($r['document_type'],array('label','waybill','combined'),true))$print=wp_nonce_url(add_query_arg(array('action'=>'hm_mahex_print_waybill','order_id'=>(int)$r['order_id'],'document'=>$r['document_type']),admin_url('admin-post.php')),'hm_mahex_print_waybill:'.(int)$r['order_id']);$mark=wp_nonce_url(add_query_arg(array('action'=>'hm_mahex_v1_print_mark','id'=>(int)$r['id']),admin_url('admin-post.php')),'hm_mahex_v1_print_mark:'.(int)$r['id']);echo '<tr><td>'.(int)$r['id'].'</td><td>#'.(int)$r['order_id'].'</td><td>'.esc_html($r['document_type']).'</td><td>'.(int)$r['copies'].'</td><td>'.esc_html($r['created_at']).'</td><td>'.($print?'<a target="_blank" class="button button-small" href="'.esc_url($print).'">چاپ</a> ':'').'<a class="button button-small" href="'.esc_url($mark).'">انجام شد</a></td></tr>';}echo '</tbody></table></section>';
		echo '<script>(function(){const list=document.getElementById("hmv1-label-fields"),input=document.getElementById("hmv1-label-fields-input");if(!list||!input)return;let drag=null;const sync=()=>input.value=[...list.children].map(x=>x.dataset.key).join(",");list.addEventListener("dragstart",e=>{drag=e.target.closest("li")});list.addEventListener("dragover",e=>{e.preventDefault();const t=e.target.closest("li");if(drag&&t&&t!==drag){const r=t.getBoundingClientRect();list.insertBefore(drag,e.clientX<r.left+r.width/2?t:t.nextSibling);sync();}});list.addEventListener("drop",e=>{e.preventDefault();sync()});sync();})();</script>';
