	private static function reports(): void { $days=max(1,min(3650,absint($_GET['days']??30)));$s=Reports::summary($days);echo '<form method="get"><input type="hidden" name="page" value="'.self::PAGE.'"><input type="hidden" name="tab" value="reports"><select name="days"><option value="7" '.selected($days,7,false).'>۷ روز</option><option value="30" '.selected($days,30,false).'>۳۰ روز</option><option value="90" '.selected($days,90,false).'>۹۰ روز</option><option value="365" '.selected($days,365,false).'>یک سال</option></select> <button class="button">اعمال</button></form><div class="hmv1-grid hmv1-section">';self::kpi('سفارش',$s['orders']);self::money('درآمد کل ارسال',$s['shipping']+$s['packaging']);self::money('هزینه حمل',$s['carrier']);self::money('سود',$s['profit']);self::money('هزینه برگشتی',$s['return_cost']);echo '</div><div class="hmv1-two"><section class="hmv1-card"><h2>سودآوری شهرها</h2><table class="widefat striped"><thead><tr><th>شهر</th><th>سفارش</th><th>درآمد</th><th>سود</th></tr></thead><tbody>';foreach(Reports::cities($days) as $r)echo '<tr><td>'.esc_html($r['province'].' / '.$r['city']).'</td><td>'.(int)$r['orders'].'</td><td>'.wp_kses_post(wc_price((float)$r['revenue'])).'</td><td>'.wp_kses_post(wc_price((float)$r['profit'])).'</td></tr>';echo '</tbody></table></section><section class="hmv1-card"><h2>سودآوری مشتریان</h2><table class="widefat striped"><thead><tr><th>مشتری</th><th>سفارش</th><th>درآمد</th><th>سود</th></tr></thead><tbody>';foreach(Reports::customers($days) as $r)echo '<tr><td>'.esc_html($r['customer_name']).'</td><td>'.(int)$r['orders'].'</td><td>'.wp_kses_post(wc_price((float)$r['revenue'])).'</td><td>'.wp_kses_post(wc_price((float)$r['profit'])).'</td></tr>';echo '</tbody></table></section></div>'; }

	private static function diagnostics(): void { $issues=Diagnostics::scan();$qual=get_transient('hm_mahex_v1_qualification_'.get_current_user_id());$setup=SetupVerifier::checks();echo '<section class="hmv1-card"><h2>Setup Verification</h2><table class="widefat striped"><thead><tr><th>بخش</th><th>وضعیت</th><th>جزئیات</th></tr></thead><tbody>';foreach($setup as $c)echo '<tr><td>'.esc_html($c['label']).'</td><td class="'.(!empty($c['ok'])?'hmv1-ok':'hmv1-bad').'">'.(!empty($c['ok'])?'آماده':'نیاز به تنظیم').'</td><td>'.esc_html($c['detail']).'</td></tr>';echo '</tbody></table></section>';echo '<section class="hmv1-card"><h2>Database Integrity / Repair Center</h2><table class="widefat striped"><thead><tr><th>شدت</th><th>مشکل</th><th>عملیات</th></tr></thead><tbody>';foreach($issues as $i){$cls='success'===$i['severity']?'hmv1-ok':('critical'===$i['severity']?'hmv1-bad':'hmv1-warn');echo '<tr><td class="'.$cls.'">'.esc_html($i['severity']).'</td><td>'.esc_html($i['message']).'</td><td>';if($i['repairable'])echo '<a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=hm_mahex_v1_repair&code='.rawurlencode($i['code'])),'hm_mahex_v1_repair_'.$i['code'])).'">تعمیر خودکار</a>';echo '</td></tr>';}echo '</tbody></table><p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=hm_mahex_v1_reindex'),'hm_mahex_v1_reindex')).'">بازسازی Order Index</a></p></section><section class="hmv1-card hmv1-section"><h2>Performance Profiler</h2><table class="widefat striped"><thead><tr><th>بخش</th><th>تعداد</th><th>میانگین ms</th><th>P95</th><th>Max</th></tr></thead><tbody>';foreach(Profiler::summary() as $k=>$r)echo '<tr><td>'.esc_html($k).'</td><td>'.(int)$r['count'].'</td><td>'.esc_html((string)$r['avg']).'</td><td>'.esc_html((string)$r['p95']).'</td><td>'.esc_html((string)$r['max']).'</td></tr>';echo '</tbody></table></section><section class="hmv1-card hmv1-section"><h2>Release Qualification Suite</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_qualification">';wp_nonce_field('hm_mahex_v1_qualification');echo '<button class="button button-primary">اجرای تست‌های نسخه</button></form>';if(is_array($qual)){echo '<p><strong>'.(int)$qual['passed'].' / '.(int)$qual['total'].'</strong> تست Pass</p><ul>';foreach($qual['tests'] as $t)echo '<li class="'.(!empty($t['ok'])?'hmv1-ok':'hmv1-bad').'">'.(!empty($t['ok'])?'✓':'✗').' '.esc_html($t['name']).' '.esc_html($t['detail']??'').'</li>';echo '</ul>';}echo '</section>'; }

	private static function tools(): void { $backups=BackupManager::all();echo '<div class="hmv1-two"><section class="hmv1-card"><h2>Backup / Restore</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_backup">';wp_nonce_field('hm_mahex_v1_backup');echo '<button class="button button-primary">ساخت Backup</button></form><table class="widefat striped"><tbody>';foreach($backups as $b)echo '<tr><td>'.esc_html($b['created_at']??'').'</td><td>'.esc_html($b['reason']??'').'</td><td><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=hm_mahex_v1_restore&id='.rawurlencode((string)$b['id'])),'hm_mahex_v1_restore_'.$b['id'])).'">Restore</a></td></tr>';echo '</tbody></table></section><section class="hmv1-card"><h2>Export / Import</h2><p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=hm_mahex_v1_export'),'hm_mahex_v1_export')).'">دانلود تنظیمات JSON</a></p><form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_import">';wp_nonce_field('hm_mahex_v1_import');echo '<input type="file" name="file" accept=".json,application/json" required> <button class="button">Import</button></form></section></div><section class="hmv1-card hmv1-section"><h2>Reset</h2><form style="display:inline-block" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v1_partial_reset">';wp_nonce_field('hm_mahex_v1_partial_reset');echo '<select name="section"><option value="pricing">قیمت و Ruleها</option><option value="printing">چاپ</option><option value="customer">تجربه مشتری</option><option value="profiler">داده Profiler</option></select> <button class="button">Reset بخش</button></form>';if(current_user_can('manage_options')){echo '<hr><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" onsubmit="return confirm(\'تمام تنظیمات نسخه 1 پاک شود؟\')"><input type="hidden" name="action" value="hm_mahex_v1_factory_reset">';wp_nonce_field('hm_mahex_v1_factory_reset');echo '<input name="confirm" placeholder="DELETE V1" required> <button class="button button-link-delete">Factory Reset</button></form>';}echo '</section>'; }

	public static function saveSettings(): void { if(!(Roles::canSettings()||Roles::canManage()||Roles::canPack()||Roles::canPrint()))wp_die('Forbidden','',array('response'=>403));check_admin_referer('hm_mahex_v1_save_settings');$input=isset($_POST['settings'])&&is_array($_POST['settings'])?wp_unslash($_POST['settings']):array();if(!(Roles::canSettings()||Roles::canManage())){$allowed=Roles::canPrint()?array('label_font','label_watermark','label_fields','label_conditional_cod','print_queue_enabled'):array();if(Roles::canPack())$allowed=array_merge($allowed,array('packing_waste_percent','packing_max_units','critical_stock_threshold','packing_verification','barcode_verification','auto_ready_to_ship','order_columns'));$input=array_intersect_key($input,array_flip($allowed));}$current=Config::all();update_option(Config::OPTION,Config::sanitize(array_replace($current,$input)),false);ActivityLog::write('settings.saved','تنظیمات نسخه 1 ذخیره شد.');self::back(); }
	public static function saveRules(): void { self::guard('hm_mahex_v1_save_rules');$rows=isset($_POST['rules'])&&is_array($_POST['rules'])?wp_unslash($_POST['rules']):array();update_option(Config::RULES,RuleEngine::sanitizeRules($rows),false);ActivityLog::write('rules.saved','قوانین نرخ نسخه 1 ذخیره شدند.',0,array('count'=>count($rows)));self::back(); }
