	public static function restore(): void { self::sensitive();$id=isset($_GET['id'])?sanitize_text_field(wp_unslash($_GET['id'])):'';self::guard('hm_mahex_v1_restore_'.$id,true);BackupManager::restore($id);self::back(); }
	public static function export(): void { self::guard('hm_mahex_v1_export',true);nocache_headers();header('Content-Type:application/json;charset=utf-8');header('Content-Disposition:attachment;filename="mahex-v1-settings-'.gmdate('Ymd-His').'.json"');echo wp_json_encode(BackupManager::export(),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);exit; }
	public static function import(): void { self::sensitive();self::guard('hm_mahex_v1_import');if(empty($_FILES['file']['tmp_name'])||!is_uploaded_file($_FILES['file']['tmp_name'])||(int)($_FILES['file']['size']??0)>1048576)self::redirect('tools','invalid');$d=json_decode((string)file_get_contents($_FILES['file']['tmp_name']),true);if(!is_array($d)||($d['format']??'')!=='hm-mahex-v1')self::redirect('tools','invalid');BackupManager::snapshot('pre_import');if(isset($d['settings']))update_option(Config::OPTION,Config::sanitize($d['settings']),false);if(isset($d['rules']))update_option(Config::RULES,RuleEngine::sanitizeRules($d['rules']),false);if(isset($d['packaging_profiles'])&&is_array($d['packaging_profiles']))update_option(PackagingProfiles::OPTION_NAME,$d['packaging_profiles'],false);if(isset($d['warehouses'])&&is_array($d['warehouses']))update_option('hm_mahex_warehouses',$d['warehouses'],false);self::redirect('tools','imported'); }
	public static function partialReset(): void { self::guard('hm_mahex_v1_partial_reset');$section=sanitize_key((string)($_POST['section']??''));$s=Config::all();$d=Config::defaults();$keys=match($section){'pricing'=>array('min_shipping_margin_irr','margin_percent','margin_fixed_irr','margin_tiers','max_customer_shipping_irr','subsidy_percent','customer_share_percent','rounding_step_irr','psychological_ending_irr'),'printing'=>array('label_font','label_watermark','label_fields','label_conditional_cod','a4_columns','allow_customer_label','print_queue_enabled'),'customer'=>array('account_shipping_card','delivery_preferences','preferred_time','address_book','reorder_shipping'),default=>array()};foreach($keys as $k)$s[$k]=$d[$k];if('pricing'===$section)update_option(Config::RULES,array(),false);if('profiler'===$section)delete_option('hm_mahex_v1_profile_samples');update_option(Config::OPTION,$s,false);ActivityLog::write('settings.partial_reset','بخشی از تنظیمات Reset شد.',0,array('section'=>$section));self::redirect('tools','reset'); }
	public static function factoryReset(): void { self::sensitive();if(!current_user_can('manage_options'))wp_die('Forbidden','',array('response'=>403));check_admin_referer('hm_mahex_v1_factory_reset');if('DELETE V1'!==(string)($_POST['confirm']??''))self::redirect('tools','invalid');BackupManager::snapshot('pre_factory_reset');delete_option(Config::OPTION);delete_option(Config::RULES);delete_option(Config::SAVED_FILTERS);delete_option(Config::DASHBOARD_WIDGETS);delete_option('hm_mahex_v1_profile_samples');ActivityLog::write('settings.factory_reset','Factory Reset نسخه 1 انجام شد.');self::redirect('tools','reset'); }
	public static function inventoryAdjust(): void { if(!(Roles::canInventory()||Roles::canManage()))wp_die('Forbidden','',array('response'=>403));check_admin_referer('hm_mahex_v1_inventory_adjust');InventoryLedger::adjust(sanitize_key((string)($_POST['profile_id']??'')),max(0,absint($_POST['new_stock']??0)),sanitize_text_field((string)($_POST['reason']??'manual')),get_current_user_id());self::redirect('inventory','saved'); }
