	public static function saveDashboard(): void { self::access();check_admin_referer('hm_mahex_v1_save_dashboard');$allowed=array('orders','profit','inventory','activity','returns','packing');$in=array_map('sanitize_key',(array)($_POST['widgets']??array()));update_option(Config::DASHBOARD_WIDGETS,array_values(array_intersect($allowed,$in)),false);self::back(); }
	public static function saveFilter(): void { self::access();check_admin_referer('hm_mahex_v1_save_filter');$name=substr(sanitize_text_field((string)($_POST['name']??'')),0,50);$query=substr(sanitize_text_field((string)($_POST['query']??'')),0,100);if($name!==''){$v=get_option(Config::SAVED_FILTERS,array());$v=is_array($v)?$v:array();$v[sanitize_key($name)?:'filter-'.count($v)]=array('name'=>$name,'query'=>$query);update_option(Config::SAVED_FILTERS,array_slice($v,-20,null,true),false);}self::back(); }
	public static function bulkEdit(): void { if(!(Roles::canPack()||Roles::canManage()))wp_die('Forbidden','',array('response'=>403));check_admin_referer('hm_mahex_v1_bulk_edit');$ids=array_map('absint',(array)($_POST['order_ids']??array()));if(!$ids&&!empty($_POST['order_ids_text'])){$ids=array_map('absint',preg_split('/[\s,،;]+/u',sanitize_text_field((string)wp_unslash($_POST['order_ids_text'])))?:array());}$ids=array_values(array_filter(array_unique($ids)));$status=sanitize_key((string)($_POST['packing_status']??''));if(!in_array($status,array('','pending','packed','ready_to_ship'),true))$status='';foreach(array_slice($ids,0,200) as $id){$o=wc_get_order($id);if(!$o)continue;if($status!=='')$o->update_meta_data('_hm_mahex_packing_status',$status);$o->save_meta_data();OrderIndex::upsert($o);}ActivityLog::write('orders.bulk_edit','ویرایش گروهی سفارش‌ها انجام شد.',0,array('count'=>count($ids),'status'=>$status));self::back(); }
	public static function reindex(): void { self::guard('hm_mahex_v1_reindex',true);$count=Diagnostics::rebuildOrderIndex(5000);ActivityLog::write('index.rebuilt','ایندکس سفارش‌ها بازسازی شد.',0,array('count'=>$count));self::back(); }


	public static function printEnqueue(): void { if(!Roles::canPrint())wp_die('Forbidden','',array('response'=>403));check_admin_referer('hm_mahex_v1_print_enqueue');$id=absint($_POST['order_id']??0);$type=sanitize_key((string)($_POST['document_type']??'label'));$copies=max(1,min(100,absint($_POST['copies']??1)));if(!$id||!wc_get_order($id))self::redirect('labels','invalid');PrintManager::enqueue($id,$type,$copies,get_current_user_id());self::redirect('labels','saved'); }
	public static function printMark(): void { if(!Roles::canPrint())wp_die('Forbidden','',array('response'=>403));$id=absint($_GET['id']??0);check_admin_referer('hm_mahex_v1_print_mark:'.$id);PrintManager::markPrinted($id);self::redirect('labels','saved'); }

	private static function packageFromOrder(\WC_Order $order): array {$contents=array();foreach($order->get_items() as $id=>$item){$p=$item->get_product();if(!$p)continue;$contents[$id]=array('data'=>$p,'quantity'=>(int)$item->get_quantity());}return array('contents'=>$contents,'contents_cost'=>(float)$order->get_subtotal(),'destination'=>array('state'=>$order->get_shipping_state()?:$order->get_billing_state(),'city'=>$order->get_shipping_city()?:$order->get_billing_city(),'postcode'=>$order->get_shipping_postcode()?:$order->get_billing_postcode()));}
	private static function savedFilters(): void {$v=get_option(Config::SAVED_FILTERS,array());if(!is_array($v)||!$v)return;echo '<p>';foreach($v as $f)echo '<a class="button button-small" href="'.esc_url(add_query_arg(array('page'=>self::PAGE,'tab'=>'overview','s'=>$f['query']??''),admin_url('admin.php'))).'">'.esc_html($f['name']??'فیلتر').'</a> ';echo '</p>';}
	private static function notice(): void {$n=sanitize_key((string)($_GET['hm_notice']??''));$m=array('saved'=>'ذخیره شد.','invalid'=>'اطلاعات معتبر نیست.','imported'=>'تنظیمات وارد شد.','reset'=>'Reset انجام شد.','qualified'=>'تست‌های نسخه اجرا شدند.');if(isset($m[$n]))echo '<div class="notice notice-'.('invalid'===$n?'error':'success').' inline"><p>'.esc_html($m[$n]).'</p></div>';}
	private static function access(): void {if(!(Roles::canManage()||Roles::canSettings()||Roles::canPack()||Roles::canPrint()||Roles::canInventory()||Roles::canReport()))wp_die('Forbidden','',array('response'=>403));}
	private static function cap(): void {if(!(Roles::canManage()||Roles::canSettings()))wp_die('Forbidden','',array('response'=>403));}
	private static function guard(string $nonce,bool $get=false): void {self::cap();check_admin_referer($nonce);}
	private static function sensitive(): void {if(Config::bool('sensitive_lock',true)&&!current_user_can('manage_options'))wp_die('Forbidden','',array('response'=>403));}
	private static function back(): never {$url=wp_get_referer()?:admin_url('admin.php?page='.self::PAGE);wp_safe_redirect(add_query_arg('hm_notice','saved',$url));exit;}
	private static function redirect(string $tab,string $notice): never {wp_safe_redirect(add_query_arg(array('page'=>self::PAGE,'tab'=>$tab,'hm_notice'=>$notice),admin_url('admin.php')));exit;}
	private static function kpi(string $label,int $value): void {echo '<div class="hmv1-card hmv1-kpi"><b>'.esc_html(number_format_i18n($value)).'</b><span>'.esc_html($label).'</span></div>';}
	private static function money(string $label,float $value): void {echo '<div class="hmv1-card hmv1-kpi"><b>'.wp_kses_post(wc_price($value)).'</b><span>'.esc_html($label).'</span></div>';}
	private static function check(string $key,string $label,array $s): void {echo '<label style="display:block;margin:8px"><input type="hidden" name="settings['.esc_attr($key).']" value="0"><input type="checkbox" name="settings['.esc_attr($key).']" value="1" '.checked(!empty($s[$key]),true,false).'> '.esc_html($label).'</label>';}
	private static function num(string $key,string $label,array $s,string $step='1'): void {echo '<label><span>'.esc_html($label).'</span><input type="number" step="'.esc_attr($step).'" name="settings['.esc_attr($key).']" value="'.esc_attr((string)($s[$key]??0)).'"></label>';}
	private static function text(string $key,string $label,array $s): void {echo '<label><span>'.esc_html($label).'</span><input type="text" name="settings['.esc_attr($key).']" value="'.esc_attr((string)($s[$key]??'')).'"></label>';}
	private static function area(string $key,string $label,array $s,string $placeholder=''): void {echo '<label style="display:block;margin:12px 0"><span>'.esc_html($label).'</span><textarea rows="5" class="large-text code" name="settings['.esc_attr($key).']" placeholder="'.esc_attr($placeholder).'">'.esc_textarea((string)($s[$key]??'')).'</textarea></label>';}
	private static function select(string $key,string $label,array $s,array $opts): void {echo '<label><span>'.esc_html($label).'</span><select name="settings['.esc_attr($key).']">';foreach($opts as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected((string)($s[$key]??''),(string)$v,false).'>'.esc_html($l).'</option>';echo '</select></label>';}
	private static function rawText(string $name,string $label,string $value): void {echo '<label><span>'.esc_html($label).'</span><input name="'.esc_attr($name).'" value="'.esc_attr($value).'"></label>';}
	private static function rawNum(string $name,string $label,string $value,string $step='1'): void {echo '<label><span>'.esc_html($label).'</span><input type="number" step="'.esc_attr($step).'" name="'.esc_attr($name).'" value="'.esc_attr($value).'"></label>';}
	private static function rawSelect(string $name,string $label,string $value,array $opts): void {echo '<label><span>'.esc_html($label).'</span><select name="'.esc_attr($name).'">';foreach($opts as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected($value,$v,false).'>'.esc_html($l).'</option>';echo '</select></label>';}
}
